import sys
input = sys.stdin.read
data = input().split()

a = data[0].lstrip('0')
b = data[1].lstrip('0')

if len(a) < len(b):
    print("<")
elif len(a) > len(b):
    print(">")
else:
    if a < b:
        print("<")
    elif a > b:
        print(">")
    else:
        print("=")

